/* The painter walks visuals, collections, brushes and expressions by raw pointer, and since swap chain frames
 * are painted on the readback thread that walk runs beside the app's threads, which change and release the
 * same objects - leaving the editor freed a visual's children array under a walk (a raster fault reading
 * 0xffffff00ffffff). walk_lock is held exclusively for the walk; every free and realloc in this file takes it
 * shared first, so memory the walk may be reading is never returned while it runs. A thread's nested frees
 * take it once (a depth in TLS), and the painter's own frees inside the walk do not take it at all. Lists
 * that are only read under their own critical section use the plain functions, (free)() and (realloc)(). */
static SRWLOCK walk_lock = SRWLOCK_INIT;
static DWORD walk_owner;
static DWORD walk_tls = TLS_OUT_OF_INDEXES;

static void walk_guard_enter( void )
{
    DWORD tid = GetCurrentThreadId(), error;
    ULONG_PTR depth;

    if (walk_owner == tid) return;
    error = GetLastError();
    if (walk_tls == TLS_OUT_OF_INDEXES)
    {
        DWORD index = TlsAlloc();
        if (InterlockedCompareExchange( (LONG *)&walk_tls, index, TLS_OUT_OF_INDEXES ) != TLS_OUT_OF_INDEXES) TlsFree( index );
    }
    depth = (ULONG_PTR)TlsGetValue( walk_tls );
    if (!depth) AcquireSRWLockShared( &walk_lock );
    TlsSetValue( walk_tls, (void *)(depth + 1) );
    SetLastError( error );
}
static void walk_guard_leave( void )
{
    DWORD error;
    ULONG_PTR depth;

    if (walk_owner == GetCurrentThreadId()) return;
    error = GetLastError();
    depth = (ULONG_PTR)TlsGetValue( walk_tls );
    if (depth == 1) ReleaseSRWLockShared( &walk_lock );
    TlsSetValue( walk_tls, (void *)(depth - 1) );
    SetLastError( error );
}
static void guarded_free( void *ptr )
{
    if (!ptr) return;
    walk_guard_enter();
    (free)( ptr );
    walk_guard_leave();
}
static void *guarded_realloc( void *ptr, size_t size )
{
    void *ret;
    if (!ptr) return (realloc)( ptr, size );
    walk_guard_enter();
    ret = (realloc)( ptr, size );
    walk_guard_leave();
    return ret;
}
#define free(p) guarded_free(p)
#define realloc(p, n) guarded_realloc(p, n)

/* WINEDEBUG=+dcompperf: a one-line summary per second of what the presenter did, cheap enough to leave
 * on while measuring (the +dcomp trace itself costs more than the painting). */
static struct
{
    unsigned int requests, deferred, unchanged, frames, commits, swapchain_frames, presents, readbacks, walkless;
    double readback_ms, readback_max;
    double walk_ms, raster_ms, batch_ms, single_ms;
    unsigned int batched, batches, singles, retries;
    unsigned int visits, ops, pixels, verified, verify_bad;
    double paint_ms, paint_max, blit_ms, flush_ms, flush_max;
    ULONGLONG start;
} perf;
static void perf_report( void )
{
    ULONGLONG now = GetTickCount64();
    if (!perf.start) perf.start = now;
    if (now - perf.start < 1000) return;
    if (perf.frames)
        TRACE_(dcompperf)( "frames: walk %.2f ms (surface readback %.2f batched, %.2f single: %u, %u upload retries), raster %.2f ms, %u visits, %u ops, %u damaged kpixels per frame; %u surfaces read back in %u batches; verified %u, %u bad.\n",
                           perf.walk_ms / perf.frames, perf.batch_ms / perf.frames, perf.single_ms / perf.frames, perf.singles, perf.retries, perf.raster_ms / perf.frames, perf.visits / perf.frames, perf.ops / perf.frames,
                           perf.pixels / perf.frames / 1000, perf.batched, perf.batches, perf.verified, perf.verify_bad );
    if (perf.requests)
        TRACE_(dcompperf)( "%I64u ms: %u commits, swap chain %u presents %u readbacks (%.2f avg %.2f max ms) %u shown (%u without a walk), %u requests, %u deferred, %u unchanged, %u frames, paint %.2f avg %.2f max, blit %.2f avg, flush %.2f avg %.2f max.\n",
                           now - perf.start, perf.commits, perf.presents, perf.readbacks,
                           perf.readbacks ? perf.readback_ms / perf.readbacks : 0.0, perf.readback_max, perf.swapchain_frames, perf.walkless, perf.requests, perf.deferred, perf.unchanged, perf.frames,
                           perf.frames ? perf.paint_ms / perf.frames : 0.0, perf.paint_max,
                           perf.frames ? perf.blit_ms / perf.frames : 0.0 , perf.frames ? perf.flush_ms / perf.frames : 0.0, perf.flush_max);
    memset( &perf, 0, sizeof(perf) );
    perf.start = now;
}

/* Last desktop-target HWND — Commit paints it until a real presenter exists. */
static HWND last_desktop_hwnd;
/* Scene bookkeeping for the presenter: every state-changing entry point bumps the generation, and a
 * frame is only painted when something changed, or changed within the last two seconds (time-driven
 * animations and expressions move without any call). XAML commits ~60 times a second regardless. */
static LONG scene_generation;
static ULONGLONG scene_change_tick;
/* XAML builds each frame's changes on its UI thread and ends them with CommitMainDevice, which Windows
 * applies atomically. Here changes land in the tree as they are made, and paints also start from the other
 * UI thread's commits (Shapr3D has two) and from the swap chain and repaint timers, so a paint could show half
 * a batch: when a menu's open transition ends XAML takes its subtree down and rebuilds it, and the other
 * thread's commit painted in between - the menu vanished for a frame. A batch is open on a committing thread
 * from its first change to its commit, and every paint but the commit's own waits for it (present_desktop_hwnd),
 * for at most XAML_BATCH_WAIT ms in case the changes were made outside a frame and no commit follows. That was
 * 50 ms, and at 3440 wide XAML takes 70 ms and more to build a frame that rebuilds a toolbar (selecting the
 * drone's folder in Shapr3D): the paint that slipped in drew its new buttons at the window's origin, with the
 * position still unset. Only batches that insert or remove visuals are waited for, so the orbit is unaffected. */
#define XAML_BATCH_WAIT 250
static struct xaml_batch { DWORD thread; LONG open; LONG structural; ULONGLONG start; } xaml_batches[4];
/* Held exclusively by the painter while it walks the tree and checks for open batches, and shared by a XAML
 * thread while it opens one: so a batch either opens before a walk (which then waits for its commit) or after
 * it. Painting runs on the swap chain's readback thread and on a repaint timer, not only on the UI thread. */
/* walk_lock itself is defined at the top of the file, with the free/realloc guard */
static CRITICAL_SECTION present_cs;
static void scene_changed( void )
{
    DWORD tid = GetCurrentThreadId();
    unsigned int i;

    InterlockedIncrement( &scene_generation );
    scene_change_tick = GetTickCount64();
    /* the painter's own bookkeeping is not a batch */
    if (HandleToULong( present_cs.OwningThread ) == tid) return;
    for (i = 0; i < ARRAY_SIZE(xaml_batches) && xaml_batches[i].thread; i++)
    {
        if (xaml_batches[i].thread != tid) continue;
        if (!xaml_batches[i].open)
        {
            walk_guard_enter();
            xaml_batches[i].start = scene_change_tick;
            xaml_batches[i].open = TRUE;
            walk_guard_leave();
            TRACE_(dcompgate)( "batch opens\n" );
        }
        break;
    }
}
/* A change that is not XAML's (a repaint request, a swap chain frame, input moving a manipulation): paint it,
 * but do not open a batch - the repaint entry points run on the UI thread, and opening one there made every
 * WM_PAINT repaint wait out XAML_BATCH_WAIT for a commit that was never coming. */
static void scene_dirty( void )
{
    InterlockedIncrement( &scene_generation );
    scene_change_tick = GetTickCount64();
}
/* A change to the tree's shape (a visual inserted or removed) in the current thread's batch. Only those batches
 * hold paints back: a menu rebuilt half-way is what flickered, while a batch that only moves and fades things
 * (the view cube during an orbit commits every frame) is safe to paint mid-way, and waiting for it cost the
 * viewport one frame in five. */
static void scene_structure_changed( void )
{
    DWORD tid = GetCurrentThreadId();
    unsigned int i;

    for (i = 0; i < ARRAY_SIZE(xaml_batches) && xaml_batches[i].thread; i++)
        if (xaml_batches[i].thread == tid && xaml_batches[i].open) xaml_batches[i].structural = TRUE;
}
/* how long a paint should still wait for an open batch, 0 for none. The committing thread's own paints
 * wait too: XAML takes a finished transition's subtree down after one commit and rebuilds it in the next
 * frame, and a repaint timer firing on that thread in between showed the context menu missing. */
static DWORD xaml_batch_wait( void )
{
    DWORD wait = 0;
    ULONGLONG now = GetTickCount64();
    unsigned int i;

    for (i = 0; i < ARRAY_SIZE(xaml_batches) && xaml_batches[i].thread; i++)
        if (xaml_batches[i].open && xaml_batches[i].structural && now - xaml_batches[i].start < XAML_BATCH_WAIT)
            wait = max( wait, XAML_BATCH_WAIT - (DWORD)(now - xaml_batches[i].start) );
    return wait;
}
static void xaml_batch_commit( void )
{
    DWORD tid = GetCurrentThreadId();
    unsigned int i;

    for (i = 0; i < ARRAY_SIZE(xaml_batches); i++)
    {
        if (!xaml_batches[i].thread && !InterlockedCompareExchange( (LONG *)&xaml_batches[i].thread, tid, 0 )) break;
        if (xaml_batches[i].thread == tid) break;
    }
    if (i < ARRAY_SIZE(xaml_batches)) xaml_batches[i].open = xaml_batches[i].structural = FALSE;
    TRACE_(dcompgate)( "commit\n" );
}
