    if (!matrix) return E_POINTER;
    TRACE( "%p: %g %g %g %g %g %g\n", impl, matrix->_11, matrix->_12, matrix->_21, matrix->_22, matrix->_31, matrix->_32 );
    impl->matrix = *matrix;
    impl->has_matrix = TRUE;
